namespace astradev_core {

/** @brief Options controlling a bounded sensor cache. */
struct CacheOptions {
  /** @brief Maximum number of samples retained by the cache. */
  std::size_t capacity{100};

  /** @brief Maximum elapsed time for which a sample is retained. */
  std::chrono::milliseconds max_age{5000};
};

/** @brief Timestamp range and result limit for a cache query. */
struct CacheQuery {
  /** @brief Inclusive lower timestamp bound in nanoseconds. */
  std::int64_t begin_timestamp_ns{0};

  /** @brief Exclusive upper timestamp bound in nanoseconds. */
  std::int64_t end_timestamp_ns{0};

  /** @brief Maximum number of samples returned by the query. */
  std::size_t limit{100};
};

/**
 * @brief RAII handle for querying a bounded sensor cache.
 * @tparam T Public sensor data type retained by the cache.
 */
template <typename T>
class SensorCache {
 public:
  using DataPtr = std::shared_ptr<const T>;

  /** @brief Constructs an inactive sensor cache handle. */
  SensorCache() = default;
  SensorCache(const SensorCache&) = delete;
  SensorCache& operator=(const SensorCache&) = delete;

  /** @brief Transfers ownership of a sensor cache handle. */
  SensorCache(SensorCache&& other) noexcept;

  /** @brief Replaces this handle with another sensor cache handle. */
  SensorCache& operator=(SensorCache&& other) noexcept;

  /** @brief Closes the cache when the handle is destroyed. */
  ~SensorCache();

  /**
   * @brief Queries retained samples in a timestamp interval.
   * @param query Half-open timestamp range and maximum result count.
   * @return Samples ordered by acquisition time, or an error result.
   */
  data::Result<std::vector<DataPtr>> Query(const CacheQuery& query) const;

  /**
   * @brief Returns the newest retained samples.
   * @param count Maximum number of samples to return.
   * @return Samples ordered by acquisition time, or an error result.
   */
  data::Result<std::vector<DataPtr>> Latest(std::size_t count) const;

  /**
   * @brief Returns the retained sample nearest to a source timestamp.
   * @param timestamp Source timestamp to search around.
   * @return The nearest sample, or kCacheMiss when the cache is empty.
   * @note When two samples are equally close, the earlier source timestamp is
   * selected. If multiple samples have that timestamp, the most recently
   * received sample is selected.
   */
  data::Result<DataPtr> GetNearestByTimestamp(
      const data::Timestamp& timestamp) const;

  /** @brief Closes this cache without affecting its source stream. */
  void Close() noexcept;

  /**
   * @brief Returns whether this cache is active.
   * @return True while the cache accepts and serves samples.
   */
  bool IsActive() const noexcept;

 private:
  /** @brief Opaque library-owned sensor cache implementation. */
  class Impl;

  explicit SensorCache(std::shared_ptr<Impl> impl);

  std::shared_ptr<Impl> impl_;

  friend class Sensor;
};

/** @brief Options controlling asynchronous subscription delivery. */
struct SubscribeOptions {
  /** @brief Number of frames retained before the oldest frame is dropped. */
  std::size_t queue_capacity{8};
};

/** @brief Move-only RAII handle for an asynchronous sensor subscription. */
class Subscription {
 public:
  /** @brief Constructs an inactive subscription handle. */
  Subscription() = default;
  Subscription(const Subscription&) = delete;
  Subscription& operator=(const Subscription&) = delete;

  /** @brief Transfers ownership of a subscription handle. */
  Subscription(Subscription&& other) noexcept;

  /** @brief Stops the current subscription and takes ownership of another. */
  Subscription& operator=(Subscription&& other) noexcept;

  /** @brief Stops callback delivery when the handle is destroyed. */
  ~Subscription();

  /** @brief Stops future callback delivery. */
  void Stop() noexcept;

  /**
   * @brief Returns whether this subscription is active.
   * @return True while callback delivery remains enabled.
   */
  bool IsActive() const noexcept;

  /**
   * @brief Returns the number of frames dropped by this subscription.
   * @return Frames evicted because the callback queue was full.
   */
  std::uint64_t DroppedFrames() const noexcept;

 private:
  /** @brief Opaque library-owned subscription implementation. */
  class Impl;

  explicit Subscription(std::shared_ptr<Impl> impl);

  std::shared_ptr<Impl> impl_;

  friend class Sensor;
};

/**
 * @brief Provides on-demand access to all supported sensor streams.
 *
 * Applications normally obtain this object from Core::GetSensor(). Each sensor
 * identifier and data type pair shares one lazily created source
 * stream. Sensor identifiers are obtained from capability discovery when it
 * is available.
 */
class Sensor final {
 public:
  Sensor(const Sensor&) = delete;
  Sensor& operator=(const Sensor&) = delete;
  Sensor(Sensor&&) = delete;
  Sensor& operator=(Sensor&&) = delete;

  /**
   * @brief Waits for the first sensor frame arriving after this call begins.
   * @tparam T One of EncodedVideoStream, RgbImage, DepthImage, PointCloud, or
   * Imu.
   * @param sensor_id Stable sensor identifier.
   * @param timeout Maximum time to wait for the next frame.
   * @return The next immutable frame, or an error result.
   */
  template <typename T>
  data::Result<std::shared_ptr<const T>> ReadOnce(
      std::string_view sensor_id,
      std::chrono::milliseconds timeout = std::chrono::milliseconds(1000));

  /**
   * @brief Delivers sensor frames asynchronously on an SDK dispatcher thread.
   * @tparam T One of EncodedVideoStream, RgbImage, DepthImage, PointCloud, or
   * Imu.
   * @param sensor_id Stable sensor identifier.
   * @param callback Function invoked for each delivered frame.
   * @param options Bounded callback queue configuration.
   * @return A move-only subscription handle, or an error result.
   */
  template <typename T>
  data::Result<Subscription> Subscribe(
      std::string_view sensor_id,
      std::function<void(std::shared_ptr<const T>)> callback,
      SubscribeOptions options = {});

  /**
   * @brief Creates an independent bounded cache for a sensor stream.
   * @tparam T One of EncodedVideoStream, RgbImage, DepthImage, PointCloud, or
   * Imu.
   * @param sensor_id Stable sensor identifier.
   * @param options Cache capacity and retention duration.
   * @return A move-only sensor cache handle, or an error result.
   */
  template <typename T>
  data::Result<SensorCache<T>> CreateCache(std::string_view sensor_id,
                                           CacheOptions options = {});

 private:
  friend class Core;

  /** @brief Constructs a stopped subsystem owned exclusively by Core. */
  Sensor();

  /** @brief Releases the subsystem owned exclusively by Core. */
  ~Sensor();

  /** @brief Forward-declared private lifecycle bridge; defined in implementation headers. */
  class Lifecycle;

  /** @brief Opaque library-owned sensor implementation. */
  class Impl;

  std::unique_ptr<Impl> impl_;
};

}  // namespace astradev_core
