#pragma once

#include <core/data/status.hpp>
#include <string>
#include <utility>

namespace astradev_core::data {

/**
 * @brief Value returned by SDK operations that may fail.
 * @tparam T Type of the success value.
 */
template <typename T>
struct Result {
  /** @brief Operation status. */
  Status status{Status::kFault};

  /** @brief Value populated when status is Status::kSuccess. */
  T value{};

  /** @brief Human-readable error detail, empty on success. */
  std::string message;

  /** @brief Returns true when the operation completed successfully. */
  explicit operator bool() const noexcept { return status == Status::kSuccess; }

  /**
   * @brief Creates a successful result.
   * @param result Value returned by the operation.
   * @return Successful result containing result.
   */
  static Result Success(T result) {
    Result value;
    value.status = Status::kSuccess;
    value.value = std::move(result);
    return value;
  }

  /**
   * @brief Creates a failed result.
   * @param error Failure status.
   * @param reason Human-readable failure detail.
   * @return Failed result containing the supplied error information.
   */
  static Result Failure(Status error, const std::string& reason) {
    Result value;
    value.status = error;
    value.message = reason;
    return value;
  }
};

/** @brief Result specialization for operations without a success value. */
template <>
struct Result<void> {
  /** @brief Operation status. */
  Status status{Status::kFault};

  /** @brief Human-readable error detail, empty on success. */
  std::string message;

  /** @brief Returns true when the operation completed successfully. */
  explicit operator bool() const noexcept { return status == Status::kSuccess; }

  /** @brief Creates a successful result. */
  static Result Success() {
    Result value;
    value.status = Status::kSuccess;
    return value;
  }

  /**
   * @brief Creates a failed result.
   * @param error Failure status.
   * @param reason Human-readable failure detail.
   * @return Failed result containing the supplied error information.
   */
  static Result Failure(Status error, const std::string& reason) {
    Result value;
    value.status = error;
    value.message = reason;
    return value;
  }
};

}  // namespace astradev_core::data
