  return started;
}

// 不可恢复的错误：立刻终止进程，而不是去执行那些可能碰到"半死不活的底层"的清理逻辑。
[[noreturn]] inline void Fatal(const char* why) {
  std::fprintf(stderr, "astradev_core: fatal: %s\n", why);
  std::abort();
}

}  // namespace detail

/** @brief 管理整个进程级的服务，以及各子系统的生命周期。 */
class Core {
 public:
  /** @brief 构造出一个处于"已停止"状态的 SDK 运行时。 */
  Core();

  /** @brief 运行时销毁时，停止所有 SDK 服务。 */
  ~Core() noexcept;

  // 以下四个 = delete：禁止拷贝、禁止移动。
  // 原因：Core 内部握着机器人连接和线程，复制出第二份会导致两份连接互相打架。
  Core(const Core&) = delete;
  Core& operator=(const Core&) = delete;
  Core(Core&&) = delete;
  Core& operator=(Core&&) = delete;

  /** @brief 返回示例库的问候语（用来验证库链接是否正常）。 */
  std::string HelloWorld() const;

  /**
   * @brief 初始化 Embosa，并启动各个 SDK 子系统。
   * @return 所有必需的服务都跑起来了才返回 true。
   * @note 子系统按 sensor、control、system_mng 的顺序启动。
   */
  bool Init();

  /** @brief 返回 Embosa 和所有必需的子系统是否都在运行。 */
  bool IsRunning() const noexcept;

  /**
   * @brief 先停掉各子系统，再释放进程级服务。
   * @note 关闭顺序和启动顺序相反：system_mng、control、sensor。
   */
  void Close() noexcept;

  // 返回本 Core 实例所拥有的 WBC（全身控制）子系统。
  Control& GetControl() noexcept;
  const Control& GetControl() const noexcept;

  /** @brief 返回本 Core 实例所拥有的传感器子系统。 */
  Sensor& GetSensor() noexcept;

  /** @brief 返回只读的传感器子系统。 */
  const Sensor& GetSensor() const noexcept;

  /** @brief 返回本 Core 所拥有的系统管理子系统。 */
  system_mng::SystemMng& GetSystemMng() noexcept;

  /** @brief 返回只读的系统管理子系统。 */
  const system_mng::SystemMng& GetSystemMng() const noexcept;

 private:
  // 强制"全进程只能有一个 Core、且不能跨线程销毁"这两条约束。
  class Guard {
   public:
    Guard() {
      // exchange(true)：把标志位写成 true，同时把"旧值"返回出来。
      // 如果旧值已经是 true，说明之前已经有人构造过 Core 了，直接终止进程。
      if (detail::StartedFlag().exchange(true)) {
        detail::Fatal("Core can only be constructed once per process");
      }
      // 记下是谁（哪个线程）创建了它。
      owner_thread_ = std::this_thread::get_id();
    }

    // 析构时断言：必须在同一个线程里销毁。
    ~Guard() { assert(std::this_thread::get_id() == owner_thread_); }

   private:
    // 创建 Guard 的那个线程 id，在析构函数里用来做断言。
    std::thread::id owner_thread_;
  };

  // 成员变量的构造顺序 = 这里的声明顺序。guard_ 排第一是故意的：
  // 它先构造，如果进程里已经有 Core，在这里就直接终止，后面的成员根本不会被构造。
  Guard guard_;
  Control control_;
  Sensor sensor_;
  system_mng::SystemMng system_mng_;
};

inline std::string Core::HelloWorld() const {
#ifdef NDEBUG
  // release 构建会定义 NDEBUG，走这一支。
  return "Hello World!";
#else
  // debug 构建走这一支。
  return "Hello World! DEBUG!";
#endif
}

// 用来验证第三方库能否正常使用；实现在 src/3rdparty.cpp。
int ProbeThirdParty();

// 用来验证 sensor_proto 依赖能否正常使用；实现在 src/3rdparty.cpp。
int ProbeSensorProto();

