/**
 * @brief 通过 WBC 服务对全身关节进行控制。
 *
 * 应用一般是通过 Core::GetControl() 拿到这个对象；
 * 只要 Core 还活着，这个对象就一直有效。
 */
class Control final {
 public:
  // 禁止拷贝、禁止移动：一个 Core 只对应一个 Control。
  Control(const Control&) = delete;
  Control& operator=(const Control&) = delete;
  Control(Control&&) = delete;
  Control& operator=(Control&&) = delete;

  /**
   * @brief 向 WBC 服务下发"绝对关节位置"目标。
   *
   * 选中哪些关节：joint_names 非空时用它，否则用 joint_groups。
   * 机身类关节组共用一个运动时长，时长 = 位移最大的那个关节的位移 / speed_rad_s，
   * 也就是说走得最远的那个关节的速度正好是 speed_rad_s。
   * 末端执行器类关节组则是立即下发。
   *
   * @param joint_positions 目标位置。顺序要么和 joint_names 一致，
   *                        要么和 joint_groups 里各关节拼接后的顺序一致。
   * @param joint_groups 要控制的关节组，例如 "left_arm"。
   * @param joint_names 要控制的关节名；它比 joint_groups 优先级更高。
   * @param speed_rad_s 关节最大速度，单位 rad/s，必须为正数。
   * @return Result：服务接受该目标时 status 为 Status::kSuccess；
   *         参数非法时为 Status::kInvalidInput；
   *         某个关节查不到实测状态时为 Status::kDataFetchFailed；
   *         否则是其他错误状态。
   * @note 这个函数在服务"接受"目标后就返回了，不会等关节真正走到位。
   */
  data::Result<void> MoveJointsTo(
      const std::vector<double>& joint_positions,
      const std::vector<std::string>& joint_groups = {},
      const std::vector<std::string>& joint_names = {},
      double speed_rad_s = 0.2);

 private:
  friend class Core;

  /** @brief 构造一个处于已停止状态的子系统，只能由 Core 独占拥有。 */
  Control();

  /** @brief 释放这个只能由 Core 独占拥有的子系统。 */
  ~Control();

  /**
   * @brief 前置声明的私有生命周期桥接类；
   *        具体定义放在实现用的头文件里。
   */
  class Lifecycle;

  /** @brief 由库自己实现的不透明 WBC 实现类。 */
  class Impl;

  std::unique_ptr<Impl> impl_;
};

